name: Scrape edfringe shows (full)

# Full rebuild: download every show from the edfringe.com GraphQL API, normalize
# into the website-ready data files, and commit them. Run manually from the
# Actions tab. For the lightweight daily top-up see the `refresh-shows` scheduled
# task, which the Claudinite scheduler runs (scraper/README.md).

on:
  workflow_dispatch:
    inputs:
      per:
        description: Shows per page
        required: false
        default: "50"
      min_delay:
        description: Minimum delay between requests (seconds)
        required: false
        default: "4"
      max_delay:
        description: Maximum delay between requests (seconds)
        required: false
        default: "9"
      commit:
        description: Commit the normalized data back to the repo
        type: boolean
        required: false
        default: true

permissions:
  contents: write

jobs:
  scrape:
    runs-on: ubuntu-latest
    timeout-minutes: 60
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Set up Python
=== PRICES ===
name: Fetch ticket prices (one-off)

# Real ticket amounts for every paid show, into the fetch-once cache
# data/prices.json — then regenerate the site data from it.
#
# Deliberately manual, and deliberately NOT on the nightly path. A show's price
# bands don't change through the festival the way its ticket status does. Every
# performance is priced — previews and weekends genuinely cost different money —
# and GraphQL alias batching fits a whole show's run into one request, so this
# is still ~3,500 requests. Run it once; re-run it only if the festival
# re-prices.
#
# The pass is resumable — shows already priced per performance are skipped — so
# `limit` lets a big run be taken in bites across several runs, each committing
# what it got. Entries from the old whole-show pass are re-priced rather than
# skipped, which is how the cache migrates. See scraper/README.md.

on:
  workflow_dispatch:
    inputs:
      limit:
        description: Stop after this many newly priced shows (blank = all remaining)
        required: false
        default: ""
      slug:
        description: Price a single show by slug instead (e.g. daniel-sloss-bitter)
        required: false
        default: ""
      batch_size:
        description: >-
          Performances priced per request, as GraphQL aliases. A rejected batch
          is halved and retried, so lowering this only costs requests — try 1 to
          confirm whether alias batching works at all against the live API.
        required: false
        default: "25"
      min_delay:
        description: Minimum delay between requests (seconds)
        required: false
        default: "1"
      max_delay:
=== TASKS ===
// edfringe task: refresh-shows — the Fringe data top-up, currently OFF.
//
// `frequency: 'manual'` is the off switch: a manual task has no occurrence, so
// the scheduler never instantiates it and it runs only from a work item created
// by hand. The site's scraping is off — the owner's call, the festival being
// over — and everything below is intact, so turning it back on is one token.
//
// REPLACES the "Refresh edfringe shows (daily)" workflow, deleted in the same
// commit that added this file. That workflow carried its own `cron: "20 5 * * *"`;
// the Claudinite scheduler is now the repo's only cron, so the cadence lives in
// the frequency below and the workflow's steps in `worker.sh`.
//
// `agent_model: 'none'` — the whole job is deterministic (fetch, merge,
// regenerate, commit), so there is no agent and no dispatch issue: the scheduler
// runs `code_work` as a subprocess and that is the entire task. A
// non-zero exit converges the task to one open `needs-human` issue, which is the
// replacement for the old workflow's `report-failure` job.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'refresh-shows',
  frequency: 'manual',             // OFF — no occurrence; a hand-created work item is the only way it runs
  precondition_signals: [],        // nothing in the repo's own state gates it — the trigger is upstream data
  agent_model: 'none',             // pure code; the work is the preprocessing subprocess below
  expected_outcome: 'none',        // it commits regenerated data straight to the default branch, as the workflow did — it never opens a PR
  agent_instructions: 'worker.sh', // vestigial for an agentless task; the real work is the command below
  code_work: 'bash worker.sh',
  code_work_timeout: 1800, // the retired workflow's `timeout-minutes: 30`, in seconds

  // Unconditional — what a hand-pulled run gets, and what a restored cadence
  // would get. The thing this task reacts to — shows added or edited on
  // edfringe.com — leaves no trace in this repo, so there is no signal to
  // precondition on: the only honest gate is the cadence itself, exactly as the
  // retired daily cron was. The run is cheap and self-limiting (one paged
  // `recentlyAdded=LAST_SEVEN_DAYS` pass) and commits nothing when nothing moved.
  precondition() {
    return { run: true, reason: 'the top-up is unconditional — upstream show edits leave no signal in this repo' };
  },
};
---
// edfringe task: refresh-tickets — the in-festival availability refresh,
// currently OFF.
//
// `frequency: 'manual'` is the off switch: a manual task has no occurrence, so
// the scheduler never instantiates it and it runs only from a work item created
// by hand. The site's scraping is off — the owner's call, the festival being
// over — and everything below is intact, so turning it back on is one token.
// `ticketWindow` stays the calendar gate a restored cadence would run under.
//
// Refreshes ticket status for today and every remaining festival date, writing
// through the master so every derived file regenerates from one source (#249).
//
// `schedule_after: ['edfringe/refresh-shows']` rather than a bare cadence anchor:
// it runs after refresh-shows' catalogue top-up, and the two data-committing
// tasks never share a checkout.
//
// `agent_model: 'none'` — the whole job is deterministic, so there is no agent
// and no dispatch issue: the scheduler runs `code_work` as a subprocess and that
// is the entire task. A non-zero exit converges to one open `needs-human` issue.
//
// Self-contained (imports nothing). `edinburghClock` and `ticketWindow` are
// exported beside the declaration so the gate is unit-tested directly
// (window.test.mjs) rather than only reasoned about.

// The calendar gate: the festival month, read on the Edinburgh clock.
export const FESTIVAL_MONTH = 8;

// Europe/London is UTC+1 for the ENTIRE window, so the conversion is a fixed
// one-hour shift and needs no timezone database. British Summer Time runs from
// the last Sunday in March to the last Sunday in October, so August lies strictly
// inside it with months of margin on both sides — there is no DST boundary
// anywhere near this window, and any instant whose Edinburgh wall clock reads
// August is necessarily under BST. (Instants that shift into any other month are
// rejected by the month test regardless, so the offset cannot matter there.)
// The shift is what decides the month at the instants where UTC and Edinburgh
// disagree about it — the last hours of 31 July and 31 August.
const BST_OFFSET_MS = 60 * 60 * 1000;

// The Edinburgh wall-clock month (1–12) and hour (0–23) at UTC instant `now`.
export function edinburghClock(now) {
  const local = new Date(new Date(now).getTime() + BST_OFFSET_MS);
  return { month: local.getUTCMonth() + 1, hour: local.getUTCHours() };
}

// The precondition's verdict as a pure function of the instant — `{ run, reason }`.
export function ticketWindow(now) {
  const { month, hour } = edinburghClock(now);
  const clock = `${String(hour).padStart(2, '0')}:xx Edinburgh, month ${month}`;
  if (month !== FESTIVAL_MONTH) {
    return { run: false, reason: `outside the festival — ${clock}; ticket status only moves during August` };
  }
  // No hour gate: an hours window on a task with one evaluation per slot could
  // only ever silence it.
  return { run: true, reason: `in-festival — ${clock}; refreshing ticket status` };
}

export default {
  id: 'refresh-tickets',
  frequency: 'manual',             // OFF — no occurrence; a hand-created work item is the only way it runs
  schedule_after: ['edfringe/refresh-shows'],
  precondition_signals: [],        // the gate is the calendar, not repo state
  agent_model: 'none',             // pure code; the work is the preprocessing subprocess below
  expected_outcome: 'none',        // it commits refreshed statuses straight to the default branch — no PR
  agent_instructions: 'worker.sh', // vestigial for an agentless task; the real work is the command below
  code_work: 'bash worker.sh',
  code_work_timeout: 900,

  precondition() {
    return ticketWindow(new Date());
  },
};

